import React, { useEffect, useState } from 'react';
import { useGame } from '../state/store.js';
import { assetUrl } from '../assets/registry.js';
import { formatRupees } from '../engine/format.js';
import { PARTY_LOGO_CHOICES, PARTY_FLAG_CHOICES, renderPartyLogoSVG, renderPartyFlagSVG } from '../engine/v130/partyArt.js';

function ActionButton({ children, onClick, disabled = false, reason = '' }) {
  return <span className="action-control">
    <button className="btn small" disabled={disabled} title={disabled ? reason : undefined} onClick={onClick}>{children}</button>
    {disabled && reason && <small className="disabled-reason">{reason}</small>}
  </span>;
}
function Box({ title, children }) {
  return <section className="panel engine-panel"><header className="panel-head">{title}</header><div className="panel-body">{children}</div></section>;
}
const partySections = ['Party Overview', 'Leadership', 'Members', 'Candidates', 'State Units', 'Funding', 'Manifesto', 'Alliances', 'Campaign Strategy', 'Meetings'];
const money = formatRupees;

export default function EnginePanel({ screen, section = 'Overview' }) {
  const game = useGame();
  const world = game.world;
  const [budget, setBudget] = useState('1000000');
  const [amount, setAmount] = useState('1000');
  const [loanAmount, setLoanAmount] = useState('1000000');
  const [membershipFee, setMembershipFee] = useState('100');
  const [contractMonths, setContractMonths] = useState('1');
  const [people, setPeople] = useState([]);
  const [peopleQuery, setPeopleQuery] = useState('');
  const [peopleState, setPeopleState] = useState('All');
  const [newPartyName, setNewPartyName] = useState('');
  const [newPartyAbbreviation, setNewPartyAbbreviation] = useState('');
  const [newPartyHeadquarters, setNewPartyHeadquarters] = useState('New Delhi');
  const [newPartyConstitution, setNewPartyConstitution] = useState('Internal democracy, transparent accounts and elected office-bearers.');
  const [meetingPurpose, setMeetingPurpose] = useState('Political cooperation');
  const [meetingAgenda, setMeetingAgenda] = useState('');
  const [meetingTopic, setMeetingTopic] = useState('');
  const [meetingPosition, setMeetingPosition] = useState('');
  const [meetingAgreement, setMeetingAgreement] = useState('');
  const [nominationElection, setNominationElection] = useState('');
  const [nominationSeat, setNominationSeat] = useState('');
  const [nominationCandidate, setNominationCandidate] = useState('');
  const [mediaHeadline, setMediaHeadline] = useState('');
  const [mediaBody, setMediaBody] = useState('');
  const [mediaHouse, setMediaHouse] = useState('NNN');
  const [mediaDetail, setMediaDetail] = useState('NNN');
  const [caseTitle, setCaseTitle] = useState('');
  const [caseFacts, setCaseFacts] = useState('');
  const [factionName, setFactionName] = useState('');
  const [factionPlatform, setFactionPlatform] = useState('');
  const [officeTitle, setOfficeTitle] = useState('National General Secretary');
  const [officeMemberId, setOfficeMemberId] = useState('PLAYER');
  const [defectionDestination, setDefectionDestination] = useState('NONE');
  const [stateUnitSelection, setStateUnitSelection] = useState('');
  const [manifestoCategory, setManifestoCategory] = useState('Economy');
  const [manifestoPolicyId, setManifestoPolicyId] = useState('');
  const [manifestoPolicyTitle, setManifestoPolicyTitle] = useState('');
  const [manifestoPolicyDescription, setManifestoPolicyDescription] = useState('');
  const [manifestoPolicyCost, setManifestoPolicyCost] = useState('0');
  const [manifestoPolicyPriority, setManifestoPolicyPriority] = useState('3');
  const [promiseTitle, setPromiseTitle] = useState('');
  const [promiseDetails, setPromiseDetails] = useState('');
  const [promiseCategory, setPromiseCategory] = useState('Governance');
  const [promisePolicyId, setPromisePolicyId] = useState('');
  const [promiseCost, setPromiseCost] = useState('0');
  const [promisePriority, setPromisePriority] = useState('3');
  const [promiseVoterGroup, setPromiseVoterGroup] = useState('General/Others');
  const [newPartyIdeology, setNewPartyIdeology] = useState('Centrist');
  const [newPartyColour, setNewPartyColour] = useState('#d6a23a');
  const [newPartyEmblem, setNewPartyEmblem] = useState('sun');
  const [newPartyFlag, setNewPartyFlag] = useState('horizontal-tricolour');
  const [newPartySecondaryColour, setNewPartySecondaryColour] = useState('#173d35');
  const [newPartyManifesto, setNewPartyManifesto] = useState('');
  const [error, setError] = useState('');
  const [confirmAction, setConfirmAction] = useState('');
  const [busy, setBusy] = useState(false);
  const confirm = (key, fn) => { if (confirmAction !== key) { setConfirmAction(key); return; } setConfirmAction(''); act(fn); };
  const confirmLabel = (key, label) => confirmAction === key ? `Confirm ${label}?` : label;
  const act = (fn) => {
    try { setError(''); fn(); }
    catch (cause) { setError(cause.message); }
  };
  useEffect(() => {
    if (screen !== 'Party HQ' || section !== 'People' || people.length) return;
    setBusy(true);
    fetch('/data/player-candidates.json')
      .then((response) => { if (!response.ok) throw new Error('Player candidate pool could not be loaded'); return response.json(); })
      .then(setPeople)
      .catch((cause) => setError(cause.message))
      .finally(() => setBusy(false));
  }, [screen, section, people.length]);
  if (!world) return <Box title="Simulation engine">Loading offline game data…</Box>;
  const upcoming = world.elections.filter((election) => election.status !== 'Results');
  const party = world.parties.find((item) => item.party_id === world.player.partyId);
  const activeSession = world.sessions.some((session) => session.status === 'In Session' && session.startDate === world.time.date.slice(0, 10));
  const visiblePeople = people.filter((person) => {
    const matchesQuery = `${person.full_name} ${person.profession} ${person.home_district}`.toLowerCase().includes(peopleQuery.toLowerCase());
    return matchesQuery && (peopleState === 'All' || person.state_id === peopleState);
  }).slice(0, 30);

  return <div className="engine-live-grid">
    {screen === 'Dashboard' && <Box title="Live political status">
      <div className="stats-row">
        <div className="stat"><small>Political position</small><strong>{world.player.status}</strong></div>
        <div className="stat"><small>Public mood</small><strong>{world.publicMood}/100</strong></div>
        <div className="stat"><small>Party</small><strong>{party?.short_name || 'Independent'}</strong></div>
        <div className="stat"><small>Legacy score</small><strong>{world.career.legacyScore}</strong></div>
      </div>
      <p>GDP growth {world.economy.national.growth.toFixed(1)}% · Inflation {world.economy.national.inflation.toFixed(1)}% · Unemployment {world.economy.national.unemployment.toFixed(1)}%</p>
      <ActionButton onClick={() => act(() => game.performAction('outreach'))}>Community outreach · 4h</ActionButton>
      <ActionButton onClick={() => act(() => game.performAction('speech'))}>Public speech · 2h</ActionButton>
    </Box>}

    {screen === 'Party HQ' && <>
      <div className="section-tabs">{partySections.map((name) => <button key={name} className={section === name ? 'active' : ''} onClick={() => game.go('Party HQ', name)}>{name}</button>)}</div>
      {section === 'People' && <Box title="People — 12,000 player-pool profiles">
        <p>{busy ? 'Loading candidate profiles…' : `${people.length.toLocaleString('en-IN')} player-pool profiles loaded. Recruited profiles are not assigned election tickets automatically.`}</p>
        <div className="people-filters"><input aria-label="Filter people" placeholder="Filter by name, profession or district" value={peopleQuery} onChange={(event) => setPeopleQuery(event.target.value)}/><select aria-label="Filter by home state" value={peopleState} onChange={(event) => setPeopleState(event.target.value)}><option value="All">All states / UTs</option>{world.states.map((state) => <option key={state.state_ut_id} value={state.state_ut_id}>{state.state_ut_name}</option>)}</select></div>
        {visiblePeople.map((person) => <div className="slot" key={person.candidate_id}><div><b>{person.full_name}</b><small>{person.profession} · {person.home_district} · Age {person.age}</small></div><ActionButton disabled={!party || (world.recruitedCandidates || []).includes(person.candidate_id)} reason={!party ? 'Join a party first' : 'Already recruited'} onClick={() => act(() => game.recruitPeople([person], 1))}>Recruit</ActionButton></div>)}
      </Box>}
      {section === 'State Units' && <Box title="State Units">
        <p>Each state unit has a recorded jurisdiction, establishment date, member count and state-level president. Only the party president may establish a unit.</p>
        <label>State / Union Territory<select value={stateUnitSelection} onChange={(event) => setStateUnitSelection(event.target.value)}><option value="">Select state / UT</option>{world.states.map((state) => <option key={state.state_ut_id} value={state.state_ut_id}>{state.state_ut_name}</option>)}</select></label>
        <ActionButton disabled={!party || !stateUnitSelection || !(party.leaderId === 'PLAYER' || world.player.partyOffice === 'Party President' || world.player.partyPresident)} reason={!party ? 'Create or join a party first' : !stateUnitSelection ? 'Select a state or Union Territory' : 'Only the party president may establish a state unit'} onClick={() => act(() => game.establishPartyStateUnit(stateUnitSelection))}>Establish state unit</ActionButton>
        {(party?.stateUnits || []).map((unit) => <div className="slot" key={unit.id}><div><b>{unit.stateName}</b><small>{unit.status} · Established {unit.establishedAt} · Members {unit.members} · President {unit.presidentId || 'Vacant'}</small></div></div>)}
      </Box>}
      {section === 'Funding' && <Box title="Party accounts and funding">
        <div className="stats-row"><div className="stat"><small>Party account</small><strong>{money(world.partyFunds)}</strong></div><div className="stat"><small>Personal account</small><strong>{money(world.player.money)}</strong></div></div><p>Monthly membership fee: {money(party?.membershipFee||0)} per member.</p>
        <label>Transfer amount (₹)<input type="number" min="1" value={amount} onChange={(event) => setAmount(event.target.value)}/></label>
        <ActionButton onClick={() => act(() => game.transferToParty(Number(amount)))}>Personal → Party</ActionButton>
        <ActionButton onClick={() => act(() => game.transferToPersonal(Number(amount)))}>Party → Personal</ActionButton>
        <label>Monthly membership fee per member (₹1–₹50,000)<input type="number" min="1" max="50000" value={membershipFee} onChange={(event) => setMembershipFee(event.target.value)}/></label>
        <ActionButton disabled={!party} reason="Join or create a party first" onClick={() => act(() => game.setMembershipFee(Number(membershipFee)))}>Set membership fee</ActionButton>
        <p>Permitted sources only: member fees, the configured 65% share of elected MLA/MP salaries, party bank loans and transfers from the player's personal account. Donations and donor/sponsor deals are not available.</p>
        <label>Party loan amount (₹10 lakh – ₹1 crore)<input type="number" min="1000000" max="10000000" step="100000" value={loanAmount} onChange={(event) => setLoanAmount(event.target.value)}/></label>
        <ActionButton disabled={!party} reason="Join or create a party first" onClick={() => act(() => game.requestPartyLoan(Number(loanAmount)))}>Apply for party loan</ActionButton>
        {(world.partyLoans || []).map((loan) => <div className="slot" key={loan.id}><div><b>{loan.id} · {loan.status}</b><small>Outstanding {money(loan.dueAmount)} · Warnings {loan.warnings}/3</small></div><ActionButton onClick={() => confirm(`loan-repay-${loan.id}`, () => game.payPartyLoan(loan.id))}>{confirmLabel(`loan-repay-${loan.id}`, 'Confirm repayment')}</ActionButton></div>)}
      </Box>}
      {section === 'Campaign Strategy' && <Box title="Campaign Strategy">
        <label>Broadcast contract duration (1–6 months)<select value={contractMonths} onChange={(event) => setContractMonths(event.target.value)}>{[1, 2, 3, 4, 5, 6].map((month) => <option key={month}>{month}</option>)}</select></label>
        {(world.finance.campaigns || []).map((campaign) => <div className="slot" key={campaign.id}><div><b>{campaign.label}</b><small>{campaign.billing === 'contract-monthly-prepaid' ? `${money(campaign.fee)} per month · prepaid contract` : `${money(campaign.fee)} · ${campaign.billing}`}</small></div><ActionButton disabled={!party || (campaign.billing === 'monthly' && world.activeCampaigns.some((item) => item.id === campaign.id && item.active))} reason={!party ? 'Join or create a party first' : 'Already active'} onClick={() => act(() => game.startCampaign(campaign.id, Number(contractMonths)))}>Start</ActionButton></div>)}
        {(world.activeCampaigns || []).filter((item) => item.active).map((campaign) => <div className="slot" key={`${campaign.id}-active`}><div><b>{campaign.label}</b><small>{campaign.monthsRemaining === null ? 'Monthly, ongoing' : `${campaign.monthsRemaining} months remaining`}</small></div><ActionButton onClick={() => act(() => game.stopCampaign(campaign.id))}>Stop</ActionButton></div>)}
      </Box>}
      {section === 'Members' && <Box title="Party membership"><p>Player membership status: {world.player.status}</p><p>Recorded members: {party?.members || world.player.members || 0}</p><p>Member fee: {money(party?.membershipFee || 0)} per member. Monthly fee collections debit the player's personal account and record the paying member count.</p><p>Recruited people below 25/100 loyalty become eligible to defect; loyalty changes are calculated from recorded party unity and faction conflict, not random penalties.</p><ActionButton onClick={() => game.go('Party HQ','People')}>People</ActionButton><label>Defection destination<select value={defectionDestination} onChange={(event) => setDefectionDestination(event.target.value)}><option value="NONE">Become independent</option>{world.parties.filter((item) => item.party_id !== party?.party_id).map((item) => <option key={item.party_id} value={item.party_id}>{item.party_name}</option>)}</select></label>{(world.partyMembers || []).filter((member) => member.initial_party_id === party?.party_id).map((member) => { const loyalty = Number(party?.memberLoyalty?.[member.candidate_id] ?? member.loyalty ?? 50); return <div className="slot" key={member.candidate_id}><div><b>{member.full_name}</b><small>{member.profession} · Loyalty {loyalty}/100 · {loyalty <= 25 ? 'Defection eligible' : 'Retained member'}</small></div><ActionButton disabled={loyalty > 25} reason={loyalty > 25 ? `Loyalty must fall to 25 or lower (currently ${loyalty})` : 'Record a member defection'} onClick={() => act(() => game.defectPartyMember(member.candidate_id, defectionDestination === 'NONE' ? null : defectionDestination))}>Defect</ActionButton></div>; })}{(world.institutions?.partyDefections || []).filter((item) => item.fromPartyId === party?.party_id).map((item) => <p key={item.id}>{item.memberName} · left for {item.toPartyId} · loyalty {item.loyaltyAtDeparture}/100 · {item.date}</p>)}</Box>}
      {section === 'Alliances' && <Box title="Party alliances and internal groups">{world.alliances.length ? world.alliances.map((alliance) => <p key={alliance.id}>{alliance.id}: {alliance.partyIds.join(', ')}</p>) : <p>No external alliance agreement is active.</p>}<label>Faction name<input value={factionName} onChange={(e) => setFactionName(e.target.value)}/></label><label>Faction platform<textarea rows="2" value={factionPlatform} onChange={(e) => setFactionPlatform(e.target.value)}/></label><ActionButton disabled={!party || !factionName.trim()} reason="Join or create a party and enter a faction name" onClick={() => act(() => { game.formPartyFaction({ name: factionName, platform: factionPlatform }); setFactionName(''); })}>Form internal faction</ActionButton>{(world.institutions?.partyFactions || []).filter((f) => f.partyId === party?.party_id).map((f) => <p key={f.id}>{f.name} · {f.status} · {f.members.length} founding members</p>)}</Box>}
      {section === 'Manifesto' && <Box title="Party manifesto builder">
        <p>Status: {party?.manifesto?.status || 'Draft'} · Estimated fiscal cost: {money(party?.manifesto?.estimatedTotalCost || 0)}</p>
        <label>Policy category<select value={manifestoCategory} onChange={(event) => setManifestoCategory(event.target.value)}>{['Economy','Employment','Education','Healthcare','Agriculture','Infrastructure','National Security','Social Welfare','Environment','Governance'].map((category) => <option key={category}>{category}</option>)}</select></label>
        <label>Executable policy proposal<select value={manifestoPolicyId} onChange={(event) => { const id = event.target.value; setManifestoPolicyId(id); const policy = world.policies.find((item) => item.id === id); if (policy) { setManifestoPolicyTitle(policy.name || policy.title || ''); setManifestoPolicyDescription(policy.description || ''); setManifestoPolicyCost(String(policy.cost || 0)); } }}><option value="">Select a policy proposal</option>{world.policies.map((policy) => <option key={policy.id} value={policy.id}>{policy.name || policy.title} · {policy.id}</option>)}</select></label>
        <label>Manifesto policy title<input value={manifestoPolicyTitle} onChange={(event) => setManifestoPolicyTitle(event.target.value)}/></label>
        <label>Policy details<textarea rows="2" value={manifestoPolicyDescription} onChange={(event) => setManifestoPolicyDescription(event.target.value)}/></label>
        <div className="form-row"><label>Priority (1–5)<select value={manifestoPolicyPriority} onChange={(event) => setManifestoPolicyPriority(event.target.value)}>{[1,2,3,4,5].map((value) => <option key={value}>{value}</option>)}</select></label><label>Estimated fiscal cost (₹)<input type="number" min="0" value={manifestoPolicyCost} onChange={(event) => setManifestoPolicyCost(event.target.value)}/></label></div>
        <ActionButton disabled={!party || !manifestoPolicyId || !manifestoPolicyTitle.trim()} reason={!party ? 'Create or join a party first' : !manifestoPolicyId ? 'Select an executable policy proposal' : 'Enter the policy title'} onClick={() => act(() => game.setManifestoPolicy(manifestoCategory, { title: manifestoPolicyTitle, description: manifestoPolicyDescription, priority: Number(manifestoPolicyPriority), fiscalCost: Number(manifestoPolicyCost), policyId: manifestoPolicyId }))}>Save policy commitment</ActionButton>
        {Object.entries(party?.manifesto?.categories || {}).map(([category, item]) => <div className="slot" key={category}><div><b>{category}: {item.title}</b><small>Priority {item.priority}/5 · {money(item.fiscalCost)} · Policy {item.policyId} · {item.status || 'Draft'}</small><small>{item.description}</small></div><ActionButton onClick={() => act(() => game.implementManifestoPolicy(category))}>Implement policy</ActionButton></div>)}
        <div className="divider-line"/><h3>Custom policy promises</h3>
        <label>Promise title<input value={promiseTitle} onChange={(event) => setPromiseTitle(event.target.value)}/></label>
        <label>Promise details<textarea rows="2" value={promiseDetails} onChange={(event) => setPromiseDetails(event.target.value)}/></label>
        <div className="form-row"><label>Category<select value={promiseCategory} onChange={(event) => setPromiseCategory(event.target.value)}>{['Economy','Employment','Education','Healthcare','Agriculture','Infrastructure','National Security','Social Welfare','Environment','Governance'].map((category) => <option key={category}>{category}</option>)}</select></label><label>Priority<select value={promisePriority} onChange={(event) => setPromisePriority(event.target.value)}>{[1,2,3,4,5].map((value) => <option key={value}>{value}</option>)}</select></label></div>
        <label>Linked executable policy<select value={promisePolicyId} onChange={(event) => setPromisePolicyId(event.target.value)}><option value="">Select a policy link</option>{world.policies.map((policy) => <option key={policy.id} value={policy.id}>{policy.name || policy.title} · {policy.id}</option>)}</select></label>
        <div className="form-row"><label>Target voter group<select value={promiseVoterGroup} onChange={(event) => setPromiseVoterGroup(event.target.value)}>{['Youth','Women','Farmers','Workers & Labourers','Middle-Class','Business Owners & Entrepreneurs','General/Others'].map((group) => <option key={group}>{group}</option>)}</select></label><label>Estimated fiscal cost (₹)<input type="number" min="0" value={promiseCost} onChange={(event) => setPromiseCost(event.target.value)}/></label></div>
        <ActionButton disabled={!party || !promiseTitle.trim() || !promisePolicyId} reason={!party ? 'Create or join a party first' : !promiseTitle.trim() ? 'Enter a promise title' : 'Link the promise to an executable policy'} onClick={() => act(() => { game.addManifestoPromise({ title: promiseTitle, details: promiseDetails, category: promiseCategory, priority: Number(promisePriority), estimatedCost: Number(promiseCost), linkedPolicyId: promisePolicyId, voterGroups: [promiseVoterGroup] }); setPromiseTitle(''); setPromiseDetails(''); })}>Add custom promise</ActionButton>
        {(party?.manifesto?.promises || []).map((promise) => <div className="slot" key={promise.id}><div><b>{promise.title}</b><small>{promise.category} · Priority {promise.priority}/5 · {money(promise.estimatedCost)} · {promise.voterGroups?.join(', ') || 'No voter group'} · Policy {promise.linkedPolicyId}</small><small>{promise.details}</small></div><ActionButton disabled={promise.status === 'Implementing'} reason="Promise already has an implementation record" onClick={() => act(() => game.fulfilManifestoPromise(promise.id))}>Implement promise</ActionButton></div>)}
        <ActionButton disabled={!party || !(party.manifesto?.categories && Object.keys(party.manifesto.categories).length) && !(party.manifesto?.promises || []).length} reason="Add at least one linked policy or promise" onClick={() => act(() => game.publishManifesto())}>Review and publish manifesto</ActionButton>
        <pre className="manifesto-preview">{JSON.stringify(party?.manifesto || {}, null, 2)}</pre>
      </Box>}
      {section === 'Meetings' && <Box title="Political meetings"><label>Invite party<select id="meeting-party" multiple size="5">{world.parties.filter((item) => item.party_id !== world.player.partyId).map((item) => <option key={item.party_id} value={item.party_id}>{item.party_name}</option>)}</select></label><label>Purpose<input value={meetingPurpose} onChange={(event) => setMeetingPurpose(event.target.value)}/></label><label>Agenda<textarea rows="3" value={meetingAgenda} onChange={(event) => setMeetingAgenda(event.target.value)}/></label><ActionButton disabled={!party || world.parties.length < 2} reason={!party ? 'Join or create a party first' : 'Select one or more parties'} onClick={() => { const select = document.getElementById('meeting-party'); const partyIds = [...(select?.selectedOptions || [])].map((option) => option.value); act(() => game.sendMeetingInvitations({ partyIds, purpose: meetingPurpose, agenda: meetingAgenda })); }}>Send invitation</ActionButton>{(world.institutions?.meetingInvitations || []).map((item) => <div className="slot" key={item.id}><div><b>{item.purpose}</b><small>{item.status} · {item.sentAt}{item.respondedAt ? ` · Responded ${item.respondedAt}` : ''}</small></div>{item.status === 'Pending' && <small>Awaiting invited party response</small>}</div>)}{(world.institutions?.meetings || []).map((item) => <div className="slot" key={item.id}><div><b>{item.purpose}</b><small>{item.scheduledDate} · {item.status}</small></div><ActionButton disabled={item.status !== 'Scheduled' || world.time.date.slice(0,10) < item.scheduledDate} reason={item.status !== 'Scheduled' ? 'Meeting is not awaiting attendance' : `Scheduled for ${item.scheduledDate}`} onClick={() => act(() => game.attendMeeting(item.id))}>Attend</ActionButton>{item.status === 'In Progress' && <><label>Discussion topic<input value={meetingTopic} onChange={(event) => setMeetingTopic(event.target.value)}/></label><label>Position / discussion record<textarea rows="2" value={meetingPosition} onChange={(event) => setMeetingPosition(event.target.value)}/></label><ActionButton disabled={!meetingTopic.trim()} reason="Enter a discussion topic" onClick={() => act(() => { game.recordMeetingDiscussion(item.id, { topic: meetingTopic, position: meetingPosition }); setMeetingTopic(''); setMeetingPosition(''); })}>Record discussion</ActionButton><label>Agreement type<select value={meetingAgreement} onChange={(event) => setMeetingAgreement(event.target.value)}><option value="">No agreement</option>{['Political cooperation','Pre-election alliance','Post-election alliance','Seat-sharing agreement','Coalition government','Common manifesto','Leadership agreement','Ministry-sharing proposal','Support agreement'].map((value) => <option key={value}>{value}</option>)}</select></label><ActionButton onClick={() => act(() => game.concludeMeeting(item.id, { outcome: meetingAgreement ? `${meetingAgreement} concluded.` : 'Discussion concluded; no binding agreement.', agreementType: meetingAgreement || null, terms: { agenda: item.agenda, discussion: item.discussion } }))}>Conclude meeting</ActionButton></>}</div>)}</Box>}
      {section === 'Leadership' && <Box title="Leadership and internal party democracy"><p>Current party: {party?.party_name || 'No party selected'} · President: {party?.leaderId || party?.initial_leader_id || 'Not recorded'}</p><p>Leadership challenges are recorded as party elections. Candidates are ranked by recorded leadership, loyalty and support.</p><ActionButton disabled={!party || (world.institutions?.internalElections || []).some((e) => e.partyId === party.party_id && e.status === 'Open')} reason={!party ? 'Join or create a party first' : 'An internal election is already open'} onClick={() => act(() => game.startLeadershipElection())}>Open leadership election</ActionButton>{(world.institutions?.internalElections || []).filter((e) => e.partyId === party?.party_id).map((e) => <div className="slot" key={e.id}><div><b>{e.id} · {e.status}</b><small>{e.candidates.length} candidates · {e.openedAt}</small>{e.candidates.map((candidate) => <small key={candidate.candidateId}>{candidate.candidateId} · score {candidate.score}</small>)}</div>{e.status === 'Open' && (world.partyMembers || []).filter((member) => member.initial_party_id === party?.party_id && !e.candidates.some((candidate) => candidate.candidateId === member.candidate_id)).slice(0, 10).map((member) => <ActionButton key={member.candidate_id} onClick={() => act(() => game.nominateInternalCandidate(e.id, { candidateId: member.candidate_id, score: Number(member.leadership || member.influence || 50), loyalty: Number(party?.memberLoyalty?.[member.candidate_id] ?? member.loyalty ?? 50), support: Number(member.public_support || 50) }))}>Nominate {member.full_name}</ActionButton>)}<ActionButton disabled={e.status !== 'Open'} reason="Election already resolved" onClick={() => act(() => game.resolveInternalElection(e.id))}>Resolve election</ActionButton></div>)}<label>Party office<select value={officeTitle} onChange={(event) => setOfficeTitle(event.target.value)}>{['Party President','Vice President','National General Secretary','Treasurer','Campaign Manager','State President','District Secretary'].map((office) => <option key={office}>{office}</option>)}</select></label><label>Appointee<select value={officeMemberId} onChange={(event) => setOfficeMemberId(event.target.value)}><option value="PLAYER">Player</option>{(world.partyMembers || []).filter((member) => member.initial_party_id === party?.party_id).map((member) => <option key={member.candidate_id} value={member.candidate_id}>{member.full_name}</option>)}</select></label><ActionButton disabled={!party || !officeTitle.trim()} reason="Join or create a party first" onClick={() => act(() => game.appointPartyOfficeBearer({ office: officeTitle, memberId: officeMemberId }))}>Appoint office-bearer</ActionButton>{(world.institutions?.disciplinaryRecords || []).filter((r) => r.partyId === party?.party_id).map((r) => <p key={r.id}>{r.memberId}: {r.action} — {r.reason}</p>)}</Box>}
      {section === 'Candidates' && <Box title="Candidates">
        <p>Only the party president or an authorised party leader can select candidates. The Election Commission charges ₹5,000 per submitted candidate and reviews every nomination.</p>
        <label>Election<select value={nominationElection} onChange={(event) => { setNominationElection(event.target.value); setNominationSeat(''); }}><option value="">Select election</option>{world.elections.map((election) => <option key={election.id} value={election.id}>{election.stateName || 'Lok Sabha'} · {election.id} · {election.pollDate}</option>)}</select></label>
        <label>Constituency<select value={nominationSeat} onChange={(event) => setNominationSeat(event.target.value)}><option value="">Select constituency</option>{(game.engineData?.constituencies || []).filter((seat) => !nominationElection || (world.elections.find((election) => election.id === nominationElection)?.type === 'assembly' ? seat.legislature_type === 'ASSEMBLY' && seat.state_ut_id === world.elections.find((election) => election.id === nominationElection)?.stateId : seat.legislature_type === 'LOK_SABHA')).map((seat) => <option key={seat.constituency_id} value={seat.constituency_id}>{seat.constituency_name || seat.constituency_id} · {seat.state_ut_name || seat.state_ut_id}</option>)}</select></label>
        <label>Recruited candidate<select value={nominationCandidate} onChange={(event) => setNominationCandidate(event.target.value)}><option value="">Select recruited candidate</option>{(world.partyMembers || []).filter((person) => person.initial_party_id === party?.party_id).map((person) => <option key={person.candidate_id} value={person.candidate_id}>{person.full_name} · {person.home_district}</option>)}</select></label>
        <ActionButton disabled={!party || !nominationElection || !nominationSeat || !nominationCandidate || world.partyFunds < 5000 || !(party.leaderId === 'PLAYER' || world.player.partyOffice === 'Party President' || world.player.partyPresident)} reason={!party ? 'Join or create a party first' : !(party.leaderId === 'PLAYER' || world.player.partyOffice === 'Party President' || world.player.partyPresident) ? 'Only the party leader may select candidates' : world.partyFunds < 5000 ? 'The party account needs ₹5,000' : 'Select an election, constituency and recruited candidate'} onClick={() => act(() => game.submitCandidateNomination({ electionId: nominationElection, constituencyId: nominationSeat, candidateId: nominationCandidate, partyId: party.party_id }))}>Submit nomination · ₹5,000</ActionButton>
        <ActionButton disabled={!party || !nominationElection || !(party.leaderId === 'PLAYER' || world.player.partyOffice === 'Party President' || world.player.partyPresident) || world.time.date.slice(0,10) < (world.elections.find((item) => item.id === nominationElection)?.nominationOpenDate || '0000-00-00') || world.time.date.slice(0,10) > (world.elections.find((item) => item.id === nominationElection)?.nominationCloseDate || '9999-99-99')} reason={!party ? 'Join or create a party first' : !(party.leaderId === 'PLAYER' || world.player.partyOffice === 'Party President' || world.player.partyPresident) ? 'Only the party leader may select candidates' : 'Auto-fill is available during the official nomination window'} onClick={() => act(() => { const election = world.elections.find((item) => item.id === nominationElection); const seats = (game.engineData?.constituencies || []).filter((seat) => election?.type === 'assembly' ? seat.legislature_type === 'ASSEMBLY' && seat.state_ut_id === election.stateId : seat.legislature_type === 'LOK_SABHA'); const existing = new Set((world.institutions?.candidateNominations || []).filter((item) => item.electionId === election.id && item.partyId === party.party_id && item.status !== 'Withdrawn').map((item) => item.constituencyId)); const assignments = game.autoFill(seats.filter((seat) => !existing.has(seat.constituency_id)), world.partyMembers || [], { partyId: party.party_id }); if (world.partyFunds < assignments.length * 5000) throw new Error(`Auto-fill needs ${money(assignments.length * 5000)} for ${assignments.length} candidate filings`); for (const assignment of assignments) game.submitCandidateNomination({ electionId: election.id, constituencyId: assignment.seatId, candidateId: assignment.candidateId, partyId: party.party_id }); })}>Auto-fill eligible seats ({(world.partyMembers || []).filter((person) => person.initial_party_id === party?.party_id).length} recruited)</ActionButton>
        {(world.institutions?.candidateNominations || []).filter((item) => item.partyId === party?.party_id).map((item) => <div className="slot" key={item.id}><div><b>{item.candidateId} · {item.constituencyId}</b><small>{item.electionId} · {item.status} · scrutiny {item.scrutinyDate} · withdrawal {item.withdrawalDeadline}</small></div>{item.status === 'Submitted' && <ActionButton disabled={world.time.date.slice(0,10) < item.scrutinyDate} reason={world.time.date.slice(0,10) < item.scrutinyDate ? `Scrutiny opens ${item.scrutinyDate}` : 'Nomination can be reviewed'} onClick={() => act(() => game.scrutiniseNomination(item.id, 'Approved', 'Eligibility documents verified.'))}>Approve nomination</ActionButton>}{['Submitted','Approved'].includes(item.status) && <ActionButton onClick={() => act(() => game.withdrawNomination(item.id))}>Withdraw</ActionButton>}</div>)}
      </Box>}

      {section === 'Party Overview' && <Box title="Party Overview"><p>{party?.party_name || 'You are currently an unaffiliated citizen.'}</p><p>Members: {world.player.members || party?.members || 0} · Party funds: {money(world.partyFunds)}</p><p>Public support: {party?.public_support ?? 0} · Organisation: {party?.organisation_strength ?? 0}</p><ActionButton disabled={!party} reason="Join or create a party first" onClick={() => game.go('Parties')}>Browse parties</ActionButton><ActionButton disabled={!!party} reason={party ? 'Resign from your current party before registering another' : 'Submit a party registration application'} onClick={() => game.go('Elections','Election Commission')}>Register a new party</ActionButton></Box>}
    </>}

    {screen === 'Elections' && <>
      <div className="section-tabs">{['Election Calendar','Election Commission','Constituencies','Candidates','Nominations','Campaigns','Counting & Results','Complaints & Courts','By-elections'].map((name) => <button key={name} className={section === name ? 'active' : ''} onClick={() => game.go('Elections',name)}>{name}</button>)}</div>
      {section === 'Election Calendar' && <Box title="Election Centre">
        <div className="stats-row">{[['Registered parties',world.parties.filter((item) => item.registrationStatus === 'Registered' || !item.playerCreated).length],['Pending applications',(world.institutions?.partyApplications || []).filter((item) => item.status === 'Pending').length],['Approved applications',(world.institutions?.partyApplications || []).filter((item) => item.status === 'Approved').length],['Nominations',(world.institutions?.candidateNominations || []).length]].map(([label,value]) => <div className="stat" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div>
        <div className="engine-art-row"><img src={assetUrl('thumb.elections.counting')} alt="Counting"/><img src={assetUrl('thumb.elections.courts')} alt="Election disputes"/></div>
        {upcoming.map((election) => <div className="slot" key={election.id}><div><b>{election.stateName || 'Lok Sabha'} — {election.type}</b><small>Announcement {election.announcementDate} · Campaign {election.campaignStartDate} to {election.campaignEndDate} · Nominations {election.nominationOpenDate} to {election.nominationCloseDate} · Scrutiny {election.scrutinyDate} · Withdrawal {election.withdrawalDeadline} · Poll {election.pollDate} · Results {election.resultsDate} · {election.totalSeats} seats · {election.status}</small></div><ActionButton disabled={world.time.date.slice(0,10) !== election.pollDate || !!game.electionProgress} reason={world.time.date.slice(0,10) !== election.pollDate ? `Available on ${election.pollDate}` : 'Election simulation is already running'} onClick={() => game.runElection(election.id).catch((cause) => setError(cause.message))}>Start election count</ActionButton></div>)}
        {game.electionProgress && <p>Simulation progress: {game.electionProgress.done.toLocaleString()} / {game.electionProgress.total.toLocaleString()}</p>}
      </Box>}
      {section === 'Election Commission' && <Box title="Election Commission — Party Registration and Administration">
        <div className="stats-row">{[['Pending applications',(world.institutions?.partyApplications || []).filter((item) => item.status === 'Pending').length],['Approved',(world.institutions?.partyApplications || []).filter((item) => item.status === 'Approved').length],['Rejected',(world.institutions?.partyApplications || []).filter((item) => item.status === 'Rejected').length],['Available symbols',(world.institutions?.symbols?.available || []).length]].map(([label,value]) => <div className="stat" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div>

        <p>Registration fee: ₹10,000 from the personal account. No minimum influence or membership requirement. The Election Commission decision is due seven in-game days after submission.</p>
        <label>Official party name<input value={newPartyName} onChange={(event) => setNewPartyName(event.target.value)} maxLength={80}/></label>
        <label>Abbreviation<input value={newPartyAbbreviation} onChange={(event) => setNewPartyAbbreviation(event.target.value.toUpperCase())} maxLength={12}/></label>
        <label>Headquarters — State / UT / New Delhi<select value={newPartyHeadquarters} onChange={(event) => setNewPartyHeadquarters(event.target.value)}>{['New Delhi', ...world.states.map((state) => state.state_ut_name || state.state_name).filter(Boolean)].map((state) => <option key={state}>{state}</option>)}</select></label>
        <label>Ideology<select value={newPartyIdeology} onChange={(event) => setNewPartyIdeology(event.target.value)}>{['Centrist','Centre-left','Centre-right','Social democratic','Conservative','Green','Regionalist','Progressive','Left','Centre','Right'].map((item) => <option key={item}>{item}</option>)}</select></label>
        <label>Primary party colour<input type="color" value={newPartyColour} onChange={(event) => setNewPartyColour(event.target.value)}/></label>
        <label>Secondary party colour<input type="color" value={newPartySecondaryColour} onChange={(event) => setNewPartySecondaryColour(event.target.value)}/></label>
        <label>Generated logo design — 24 choices<select value={newPartyEmblem} onChange={(event) => setNewPartyEmblem(event.target.value)}>{PARTY_LOGO_CHOICES.map((choice) => <option key={choice.id} value={choice.id}>{choice.label}</option>)}</select></label>
        <label>Generated flag layout — 12 choices<select value={newPartyFlag} onChange={(event) => setNewPartyFlag(event.target.value)}>{PARTY_FLAG_CHOICES.map((choice) => <option key={choice.id} value={choice.id}>{choice.label}</option>)}</select></label>
        <div className="party-art-preview"><span><b>Logo preview</b><img alt="Generated party logo preview" src={`data:image/svg+xml,${encodeURIComponent(renderPartyLogoSVG(newPartyEmblem, newPartyColour, newPartySecondaryColour))}`}/></span><span><b>Flag preview</b><img className="party-flag-preview" alt="Generated party flag preview" src={`data:image/svg+xml,${encodeURIComponent(renderPartyFlagSVG(newPartyFlag, newPartyColour, newPartySecondaryColour))}`}/></span></div>
        <label>Party constitution<textarea rows="3" value={newPartyConstitution} onChange={(event) => setNewPartyConstitution(event.target.value)}/></label>
        <label>Initial manifesto — required<textarea rows="4" value={newPartyManifesto} onChange={(event) => setNewPartyManifesto(event.target.value)} placeholder="Describe the party's initial policy commitments."/></label>
        <ActionButton disabled={newPartyName.trim().length < 3 || newPartyAbbreviation.trim().length < 2 || !newPartyHeadquarters.trim() || !newPartyConstitution.trim() || !newPartyManifesto.trim() || world.player.money < 10000} reason={!newPartyName.trim() ? 'Enter an official party name' : !newPartyAbbreviation.trim() ? 'Enter an abbreviation' : !newPartyManifesto.trim() ? 'An initial manifesto is required' : world.player.money < 10000 ? 'You need ₹10,000 in your personal account' : 'Complete the constitution and headquarters fields'} onClick={() => act(() => game.createParty({ name: newPartyName, abbreviation: newPartyAbbreviation, headquarters: newPartyHeadquarters, ideology: newPartyIdeology, politicalPosition: newPartyIdeology, primaryColour: newPartyColour, secondaryColour: newPartySecondaryColour, logo: newPartyEmblem, flag: newPartyFlag, constitution: newPartyConstitution, manifesto: { status: 'Draft', initialText: newPartyManifesto, categories: {}, promises: [] } }))}>Submit registration · ₹10,000</ActionButton>
        {(world.institutions?.partyApplications || []).map((application) => <div className="slot" key={application.id}><div><b>{application.name} ({application.abbreviation})</b><small>{application.id} · {application.status} · Decision: {application.decisionDate || 'Awaiting correction'}</small>{application.correctionNotes && <small>EC review: {application.correctionNotes}</small>}</div>{application.status === 'Changes Required' && <ActionButton onClick={() => act(() => game.resubmitPartyCorrections(application.id, { name: newPartyName || application.name, abbreviation: newPartyAbbreviation || application.abbreviation, constitution: newPartyConstitution || application.constitution, manifesto: { ...application.manifesto, initialText: newPartyManifesto || application.manifesto?.initialText }, headquarters: newPartyHeadquarters, logo: newPartyEmblem, flag: newPartyFlag, primaryColour: newPartyColour, secondaryColour: newPartySecondaryColour, ideology: newPartyIdeology, politicalPosition: newPartyIdeology }))}>Resubmit corrections</ActionButton>}</div>)}
      
        <h3>Election Commission notices</h3>{(world.notifications || []).filter((item) => item.type === 'Election Commission' || item.target === 'Elections').slice(0,12).map((item) => <p key={item.id}>{item.title} · {item.body}</p>)}
        <h3>Symbol allocation</h3>{Object.entries(world.institutions?.symbols?.allocated || {}).map(([symbol,partyId]) => <p key={symbol}>{symbol} · {partyId}</p>)}
      </Box>}
      {section === 'Constituencies' && <Box title="Constituencies">
        <p>Lok Sabha: 543 seats. State Assemblies: {world.seatCounts.reduce((sum,row) => sum + Number(row.assembly_seats || 0),0).toLocaleString('en-IN')} seats across jurisdictions with legislatures.</p>
        {(world.seatCounts || []).map((row) => <div className="slot" key={row.state_ut_id}><div><b>{row.state_ut_name}</b><small>Lok Sabha {row.lok_sabha_seats} · Assembly {row.assembly_seats}</small></div></div>)}
      </Box>}
      {section === 'Candidates' && <Box title="Candidates">
        <p>Recruited candidate records and current party affiliation. Formal tickets are filed and scrutinised in Nominations.</p>
        {(world.partyMembers || []).map((candidate) => <div className="slot" key={candidate.candidate_id}><div><b>{candidate.full_name}</b><small>{candidate.candidate_id} · {candidate.initial_party_id} · {candidate.home_district} · Age {candidate.age}</small></div></div>)}
      </Box>}
      {section === 'Nominations' && <Box title="Candidate nominations and scrutiny">
        <p>Nomination scrutiny follows the published Election Commission calendar. Approved candidates are placed on the final constituency ballot; withdrawn or rejected candidates are excluded.</p>
        {(world.institutions?.candidateNominations || []).map((item) => <div className="slot" key={item.id}><div><b>{item.candidateId} · {item.constituencyId}</b><small>{item.electionId} · Party {item.partyId} · {item.status} · Scrutiny {item.scrutinyDate} · Withdrawal {item.withdrawalDeadline}</small>{item.scrutinyReason && <small>{item.scrutinyReason}</small>}</div>{item.status === 'Submitted' && <ActionButton disabled={world.time.date.slice(0,10) < item.scrutinyDate} reason={world.time.date.slice(0,10) < item.scrutinyDate ? `Scrutiny opens ${item.scrutinyDate}` : 'Review the candidate record'} onClick={() => act(() => game.scrutiniseNomination(item.id,'Approved','Identity, party affiliation and eligibility documents verified.'))}>Approve nomination</ActionButton>}{item.status === 'Submitted' && <ActionButton disabled={world.time.date.slice(0,10) < item.scrutinyDate} reason="Scrutiny has not opened" onClick={() => act(() => game.scrutiniseNomination(item.id,'Rejected','Eligibility or party affiliation could not be verified.'))}>Reject nomination</ActionButton>}</div>)}
        {(world.elections || []).filter((item) => item.finalCandidateListPublishedAt).map((election) => <p key={election.id}>Final list: {election.stateName || 'Lok Sabha'} · {election.finalCandidateList?.length || 0} candidates · Published {election.finalCandidateListPublishedAt}</p>)}
      </Box>}
      {section === 'Counting & Results' && <Box title="Counting & Results">
        {(world.elections || []).filter((item) => item.resultPublished || item.status === 'Results').map((election) => <div className="slot" key={election.id}><div><b>{election.stateName || 'Lok Sabha'} · {election.id}</b><small>{election.status} · Poll {election.pollDate} · Count {election.resultsDate} · Certification {election.certificationStatus || 'Pending'}</small><small>{Object.entries(election.result?.seatTally || {}).map(([partyId,seats]) => `${partyId}: ${seats}`).join(' · ')}</small></div><ActionButton disabled={!election.resultPublished || election.certificationStatus === 'Certified'} reason={!election.resultPublished ? 'Results have not been published' : 'Already certified'} onClick={() => act(() => game.certifyElectionResult(election.id))}>Certify official result</ActionButton></div>)}
      </Box>}
      {section === 'Campaigns' && <Box title="Campaigns">
        {(world.activeCampaigns || []).map((campaign) => <div className="slot" key={campaign.id}><div><b>{campaign.label}</b><small>{campaign.active ? 'Active' : 'Stopped'} · {campaign.partyId} · {campaign.startedAt} · {campaign.monthsRemaining ?? 'Monthly'}</small></div></div>)}
        {(world.parties || []).filter((item) => world.partyCampaignMetrics?.[item.party_id]).map((item) => <p key={item.party_id}>{item.party_name}: {Object.entries(world.partyCampaignMetrics[item.party_id]).map(([name,value]) => `${name} ${value}`).join(' · ')}</p>)}
      </Box>}
      {section === 'Complaints & Courts' && <Box title="Complaints & Courts"><p>Election disputes are registered, heard and appealed through the independent judiciary.</p>{(world.institutions?.courtCases || []).filter((item) => item.category === 'Election Petition').map((item) => <p key={item.id}>{item.id} · {item.title} · {item.status}</p>)}<ActionButton onClick={() => game.go('Courts')}>Open Courts</ActionButton></Box>}
      {section === 'By-elections' && <Box title="By-elections">{(world.elections || []).filter((item) => item.isByElection).length ? world.elections.filter((item) => item.isByElection).map((item) => <p key={item.id}>{item.stateName || 'Lok Sabha'} · {item.pollDate} · {item.status}</p>) : <p>No by-elections are currently scheduled. A by-election is created when a recorded vacancy triggers an Election Commission notice.</p>}</Box>}
    </>}

    {screen === 'Events' && <Box title="Event timeline and decisions">
      <p>Recorded events: {world.events.length} · Major events this month: {world.events.filter((event) => event.month === world.time.monthIndex && event.major).length}</p>
      {world.pendingDecision ? <><div className="event-art">{world.pendingDecision.art && assetUrl(`event.${world.pendingDecision.art}`) ? <img src={assetUrl(`event.${world.pendingDecision.art}`)} alt={world.pendingDecision.title}/> : <span className="gold-icon">✦</span>}</div><h3>{world.pendingDecision.title}</h3><p>{world.pendingDecision.description}</p>{world.pendingDecision.choices.map((choice) => <p key={choice.id}><ActionButton onClick={() => act(() => game.resolveDecision(choice.id))}>{choice.label}</ActionButton></p>)}</> : <p>No pending event decision. Events are generated by the monthly simulation tick.</p>}
      {world.pendingShock && <><h3>Economic warning: {world.pendingShock.name}</h3><ActionButton onClick={() => act(() => game.resolveShock('prepare'))}>Prepare response</ActionButton><ActionButton onClick={() => act(() => game.resolveShock('absorb'))}>Absorb shock</ActionButton></>}
    </Box>}

    {(screen === 'Government' || screen === 'National Budget') && <Box title="Balanced public budget">
      <p>Revenue: {money(world.economy.budget.revenue)} · Reserve: {money(world.economy.budget.reserveFund)}</p>
      <label>Revenue (₹)<input value={budget} onChange={(event) => setBudget(event.target.value)}/></label>
      <ActionButton onClick={() => act(() => game.setBudget({ revenue: Number(budget), allocations: { Home: 100000, Finance: 100000, Education: 150000, Health: 150000, Agriculture: 100000, Infrastructure: 150000, Rural: 100000, Environment: 50000, Defence: 50000, Other: 50000 } }))}>Set balanced budget</ActionButton>
      <p>Surplus: {money(world.economy.budget.surplus)}</p>
    </Box>}

    {screen === 'Parliament' && <Box title="Lok Sabha — legislative business">
      <p>{world.bills.length} bills in the register · {world.sessions.length} scheduled sessions .</p>
      {world.sessions.map((session) => <div className="slot" key={session.id}><div><b>{session.kind} Session</b><small>{session.startDate} · {session.status}</small></div><ActionButton disabled={world.time.date.slice(0, 10) !== session.startDate || session.status !== 'Scheduled'} reason={world.time.date.slice(0, 10) !== session.startDate ? 'Available on the scheduled session date' : 'Session already started'} onClick={() => act(() => game.startSession(session.id))}>Start Session</ActionButton></div>)}
      {world.bills.slice(0, 12).map((bill) => <div className="slot" key={bill.id}><div><b>{bill.name}</b><small>{bill.ministry} · {bill.status}</small></div><ActionButton disabled={bill.status !== 'Draft' || !activeSession} reason={bill.status !== 'Draft' ? 'Only Draft bills can be introduced' : 'Start a legislative session first'} onClick={() => act(() => game.introduceBill(bill.id))}>Introduce</ActionButton><ActionButton disabled={!['Introduced', 'Debating'].includes(bill.status) || !activeSession} reason={bill.status === 'Draft' ? 'Introduce this bill first' : 'Voting requires an active session'} onClick={() => act(() => game.voteBill(bill.id, 'yes'))}>Vote Yes</ActionButton></div>)}
    </Box>}

    {screen === 'State Assembly' && <Box title="State Assembly">
      <p>31 Assembly jurisdictions · 4,123 seats. The 5 no-Assembly UTs are not listed.</p>
      {world.states.filter((state) => Number(world.seatCounts.find((row) => row.state_ut_id === state.state_ut_id)?.assembly_seats || 0) > 0).map((state) => {
        const seats = world.seatCounts.find((row) => row.state_ut_id === state.state_ut_id);
        return <div className="slot" key={state.state_ut_id}><div><b>{state.state_ut_name}</b><small>{seats.assembly_seats} seats · Assembly jurisdiction</small></div><ActionButton onClick={() => game.go('State Details', state.state_ut_name)}>View Assembly</ActionButton></div>;
      })}
    </Box>}

    {screen === 'Media' && <><Box title="Media & News — seven independent media organisations"><p>Media recognition: {world.player.media}/100 · Public mood: {world.publicMood}/100</p><div className="section-tabs">{(world.institutions?.mediaHouses || []).map((house) => <button key={house.id} className={mediaDetail === house.id ? 'active' : ''} onClick={() => setMediaDetail(house.id)}>{house.id}</button>)}</div>{(() => { const house = (world.institutions?.mediaHouses || []).find((item) => item.id === mediaDetail); return house ? <div className="media-detail"><div className="media-lettermark">{house.id}</div><h3>{house.name}</h3><p>{house.format} · {house.regionalStrength}</p><div className="stats-row">{[['Credibility',house.credibility],['Reach',house.reach],['Influence',house.influence],['Sensationalism',house.sensationalism]].map(([label,value])=><div className="stat" key={label}><small>{label}</small><strong>{value}/100</strong></div>)}</div><p>Political leaning: {house.leaning} · Government stance: {house.governmentStance}</p><p>Ownership: {house.ownership}</p><p>Editorial policy: {house.editorialPolicy}</p></div> : null; })()}</Box><Box title="Publish a media report"><label>Media organisation<select value={mediaHouse} onChange={(e) => setMediaHouse(e.target.value)}>{(world.institutions?.mediaHouses || []).map((house) => <option key={house.id} value={house.id}>{house.name}</option>)}</select></label><label>Headline<input value={mediaHeadline} onChange={(e) => setMediaHeadline(e.target.value)}/></label><label>Report<textarea rows="3" value={mediaBody} onChange={(e) => setMediaBody(e.target.value)}/></label><ActionButton disabled={!mediaHeadline.trim() || !mediaBody.trim()} reason="Enter a headline and report" onClick={() => act(() => { game.publishMediaReport({ houseId: mediaHouse, headline: mediaHeadline, body: mediaBody, topic: 'Political affairs', factuality: 75, sentiment: 0 }); setMediaHeadline(''); setMediaBody(''); })}>Publish report</ActionButton>{(world.institutions?.mediaReports || []).slice(0, 8).map((report) => <div className="news" key={report.id}><b>{report.headline}</b><p>{report.body}</p><small>{report.houseId} · {report.publishedAt}</small></div>)}</Box></>}

    {screen === 'Economy' && <Box title="National economy — single source of truth">
      <div className="stats-row">{[['GDP', money(world.economy.national.gdp)], ['Growth', `${world.economy.national.growth.toFixed(1)}%`], ['Inflation', `${world.economy.national.inflation.toFixed(1)}%`], ['Unemployment', `${world.economy.national.unemployment.toFixed(1)}%`]].map(([label, value]) => <div className="stat" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div>
      <div className="engine-art-row"><img src={assetUrl('thumb.economy.agriculture')} alt="Agriculture"/><img src={assetUrl('thumb.economy.manufacturing')} alt="Manufacturing"/><img src={assetUrl('thumb.economy.trade')} alt="Trade and exports"/><img src={assetUrl('thumb.economy.infrastructure')} alt="Infrastructure"/></div>
      <p>State economies: {Object.keys(world.economy.states).length}</p>
    </Box>}

    {screen === 'Projects' && <Box title="Project register">
      <div className="engine-art-row"><img src={assetUrl('thumb.projects.greenEnergy')} alt="Green energy"/><img src={assetUrl('thumb.projects.ruralHealthcare')} alt="Rural healthcare"/><img src={assetUrl('thumb.projects.metro')} alt="Metro infrastructure"/></div>
      {world.projects.slice(0, 8).map((project) => <div className="slot" key={project.id}><div><b>{project.name}</b><small>{project.sector} · {project.status} · {money(project.cost)}</small></div><ActionButton disabled={project.status !== 'Proposed'} reason="Only proposed projects can be funded" onClick={() => act(() => game.startProject(project.id))}>Fund</ActionButton></div>)}
    </Box>}

    {screen === 'Election Commission' && <><Box title="Independent Election Commission"><div className="stats-row">{[['Registered parties',world.parties.filter((p) => p.registrationStatus === 'Registered' || !p.playerCreated).length],['Pending applications',(world.institutions?.partyApplications || []).filter((a) => a.status === 'Pending').length],['Approved applications',(world.institutions?.partyApplications || []).filter((a) => a.status === 'Approved').length],['Rejected applications',(world.institutions?.partyApplications || []).filter((a) => a.status === 'Rejected').length],['Nominations',(world.institutions?.candidateNominations || []).length]].map(([label,value])=><div className="stat" key={label}><small>{label}</small><strong>{value}</strong></div>)}</div><p>Unallocated symbols: {world.institutions?.symbols?.available?.length || 0}</p>{(world.institutions?.partyApplications || []).map((application) => <div className="slot" key={application.id}><div><b>{application.name}</b><small>{application.status} · Submitted {application.submittedAt} · Due {application.decisionDate || '—'}</small></div></div>)}{(world.institutions?.electionNotices || []).map((notice) => <div className="news" key={notice.id}><b>{notice.title}</b><p>{notice.body}</p></div>)}</Box><Box title="Certified election results">{world.elections.filter((e) => e.resultPublished).map((e) => <div className="slot" key={e.id}><div><b>{e.stateName || 'Lok Sabha'}</b><small>{e.certificationStatus || 'Awaiting certification'}</small></div><ActionButton disabled={!!e.certifiedAt} reason="Result already certified" onClick={() => act(() => game.certifyElectionResult(e.id))}>Certify result</ActionButton></div>)}</Box></>}
    {screen === 'Courts' && <Box title="Judiciary — case register"><label>Case category<select id="court-category">{['Election Petition','Constitutional Dispute','Corruption','Government Action','Defamation','Public Interest','Administrative Appeal','Loan Default'].map((x) => <option key={x}>{x}</option>)}</select></label><label>Case title<input value={caseTitle} onChange={(e) => setCaseTitle(e.target.value)}/></label><label>Supporting facts<textarea rows="4" value={caseFacts} onChange={(e) => setCaseFacts(e.target.value)}/></label><ActionButton disabled={!caseTitle.trim() || caseFacts.trim().length < 20} reason="Provide a case title and at least 20 characters of supporting facts" onClick={() => act(() => { game.fileCourtCase({ category: document.getElementById('court-category').value, title: caseTitle, facts: caseFacts }); setCaseTitle(''); setCaseFacts(''); })}>File case</ActionButton>{(world.institutions?.courtCases || []).map((item) => <div className="slot" key={item.id}><div><b>{item.id} · {item.title}</b><small>{item.court} · {item.status} · Hearing {item.hearingDate}</small></div><ActionButton disabled={!['Filed','Hearing'].includes(item.status)} reason="Case has already been decided" onClick={() => act(() => game.adjudicateCourtCase(item.id))}>Independent adjudication</ActionButton></div>)}</Box>}
    {screen === 'Meetings' && <Box title="Political meeting register"><p>Invitations, responses, three-day scheduling and agreement records.</p>{(world.institutions?.meetingInvitations || []).map((item) => <div className="slot" key={item.id}><div><b>{item.purpose}</b><small>{item.status} · {item.sentAt}{item.respondedAt ? ` · Responded ${item.respondedAt}` : ''}</small></div>{item.status === 'Pending' && <small>Awaiting invited party response</small>}</div>)}{(world.institutions?.meetings || []).map((item) => <div className="slot" key={item.id}><div><b>{item.purpose}</b><small>{item.scheduledDate} · {item.status}</small></div><ActionButton disabled={item.status !== 'Scheduled' || world.time.date.slice(0,10) < item.scheduledDate} reason={`Meeting date: ${item.scheduledDate}`} onClick={() => act(() => game.attendMeeting(item.id))}>Attend meeting</ActionButton></div>)}</Box>}
    {error && <p role="alert" className="engine-error">{error}</p>}
  </div>;
}
